// Generates the app's theme and icon data from the design files.
//
//   design/system/tokens.json  ->  src/theme/tokens.ts, src/theme/fonts.ts
//   design/system/icons/*.svg  ->  src/components/icon-data.ts
//
// Run with `npm run tokens` after copying new design files into design/.
// Never edit the generated files by hand.

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'design/system/tokens.json'), 'utf8'));
const HEADER = '// Generated by scripts/build-tokens.mjs from design/system. Do not edit.\n';

const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const px = (v) => (typeof v === 'number' ? v : Number(String(v).replace('px', '')));
const doc = (s) => (s ? `  /** ${s.replace(/\*\//g, '* /')} */\n` : '');
const list = (group) => (Array.isArray(group) ? group : group.tokens);

// ---- Fonts ---------------------------------------------------------------
// Each weight of each family is its own font face in React Native.

const FAMILIES = {
  display: { pkg: '@expo-google-fonts/alumni-sans', prefix: 'AlumniSans' },
  sans: { pkg: '@expo-google-fonts/albert-sans', prefix: 'AlbertSans' },
  hand: { pkg: '@expo-google-fonts/caveat', prefix: 'Caveat' },
};
const WEIGHT_NAMES = { 400: 'Regular', 500: 'Medium', 600: 'SemiBold', 700: 'Bold' };
const face = (family, weight) => `${FAMILIES[family].prefix}_${weight}${WEIGHT_NAMES[weight]}`;
// iOS finds a font bundled by the expo-font plugin by its PostScript name; Android and web by its file name.
// shortcut: assumes Google Fonts' "Family-Weight" PostScript names (true for every face here), check a new face's .ttf.
const postScript = (family, weight) => `${FAMILIES[family].prefix}-${WEIGHT_NAMES[weight]}`;
const fontPath = (family, weight) => `./node_modules/${FAMILIES[family].pkg}/${weight}${WEIGHT_NAMES[weight]}/${face(family, weight)}.ttf`;

// Weights the type styles use, plus the ones the screens use outside them
// (600 labels on sage buttons, 400 counts on sticky notes).
const faces = { display: new Set([600, 700]), sans: new Set([400, 500, 600, 700]), hand: new Set([400, 500, 700]) };

// ---- Type ----------------------------------------------------------------

const typeLines = [];
for (const group of tokens.type.groups) {
  for (const s of group.styles) {
    const family = s.family ?? group.family;
    const size = px(s.fontSize);
    const lh = typeof s.lineHeight === 'number' ? Math.round(size * s.lineHeight) : px(s.lineHeight);
    const ls = s.letterSpacing ? Math.round(parseFloat(s.letterSpacing) * size * 100) / 100 : 0;
    faces[family].add(s.fontWeight);
    const props = [`fontFamily: font.${face(family, s.fontWeight)}`, `fontSize: ${size}`, `lineHeight: ${lh}`];
    if (ls) props.push(`letterSpacing: ${ls}`);
    typeLines.push(`${doc(s.usage)}  ${camel(s.name)}: { ${props.join(', ')} },`);
  }
}

// ---- Shadows -------------------------------------------------------------
// React Native's new architecture understands CSS box-shadow strings.

const out = [HEADER, "import { Platform } from 'react-native';\n", "const ios = Platform.OS === 'ios';\n"];
out.push('/** Font face names: the PostScript name on iOS, the file name on Android and web. */');
out.push('export const font = {');
for (const [family, weights] of Object.entries(faces)) {
  for (const w of [...weights].sort()) out.push(`  ${face(family, w)}: ios ? '${postScript(family, w)}' : '${face(family, w)}',`);
}
out.push('} as const;\n');
out.push('export const color = {');
for (const t of list(tokens.color)) out.push(`${doc(t.usage)}  ${camel(t.name)}: '${t.value.toUpperCase()}',`);
out.push('} as const;\n');

out.push('export const type = {');
out.push(...typeLines);
out.push('} as const;\n');

for (const [name, key] of [['space', 'spacing'], ['radius', 'radius'], ['size', 'size']]) {
  out.push(`export const ${name} = {`);
  for (const t of list(tokens[key])) {
    const short = camel(t.name.replace(new RegExp(`^${name}-`), ''));
    const k = /^[0-9]/.test(short) ? `s${short}` : short;
    out.push(`${doc(t.usage)}  ${k}: ${px(t.value)},`);
  }
  out.push('} as const;\n');
}

out.push('export const shadow = {');
for (const t of list(tokens.shadow)) {
  out.push(`${doc(t.usage)}  ${camel(t.name.replace(/^shadow-/, ''))}: { boxShadow: '${t.value}' },`);
}
out.push('} as const;\n');

out.push('export type ColorName = keyof typeof color;');
out.push('export type TypeName = keyof typeof type;');
writeFileSync(join(root, 'src/theme/tokens.ts'), out.join('\n') + '\n');

// ---- Font loading --------------------------------------------------------

// The same faces are bundled into the native build by the expo-font plugin in app.json; useFonts() only loads them
// where that build isn't there (Expo Go and web).
const fontOut = [HEADER];
const fontKeys = [];
const fontPaths = [];
for (const [family, weights] of Object.entries(faces)) {
  const names = [...weights].sort().map((w) => face(family, w));
  fontKeys.push(...names);
  fontPaths.push(...[...weights].sort().map((w) => fontPath(family, w)));
  fontOut.push(`import { ${names.join(', ')} } from '${FAMILIES[family].pkg}';`);
}
fontOut.push("import { font } from './tokens';");
fontOut.push('', '/** Every font face the app uses, for useFonts() in Expo Go and on web. Native builds bundle them. */');
fontOut.push(`export const fontFaces = { ${fontKeys.map((k) => `[font.${k}]: ${k}`).join(', ')} };`);

const appPlugins = JSON.parse(readFileSync(join(root, 'app.json'), 'utf8')).expo.plugins;
const bundled = appPlugins.find((p) => Array.isArray(p) && p[0] === 'expo-font')?.[1]?.fonts ?? [];
if (JSON.stringify(bundled) !== JSON.stringify(fontPaths)) {
  throw new Error(`app.json's expo-font plugin must list exactly these fonts:\n${JSON.stringify(fontPaths, null, 2)}`);
}
writeFileSync(join(root, 'src/theme/fonts.ts'), fontOut.join('\n') + '\n');

// ---- Icons ---------------------------------------------------------------

const iconDir = join(root, 'design/system/icons');
const icons = {};
for (const file of readdirSync(iconDir).filter((f) => f.endsWith('.svg')).sort()) {
  const svg = readFileSync(join(iconDir, file), 'utf8');
  const body = svg.replace(/^<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '');
  icons[file.replace('.svg', '')] = [...body.matchAll(/<(path|circle|rect|line|polyline|ellipse)\s([^>]*?)\/?>/g)].map(
    ([, tag, attrs]) => {
      const props = {};
      for (const [, k, v] of attrs.matchAll(/([a-zA-Z-]+)="([^"]*)"/g)) props[camel(k)] = v;
      return { tag, props };
    },
  );
}
const iconOut = [HEADER];
iconOut.push('export type IconShape = { tag: string; props: Record<string, string> };');
iconOut.push(`export const iconData = ${JSON.stringify(icons, null, 2)} satisfies Record<string, IconShape[]>;`);
iconOut.push('', 'export type IconName = keyof typeof iconData;');
writeFileSync(join(root, 'src/components/icon-data.ts'), iconOut.join('\n') + '\n');

console.log(`tokens.ts, fonts.ts (${fontKeys.length} faces), icon-data.ts (${Object.keys(icons).length} icons) written.`);
